      g.fillRoundedRect(x0 + 5, y0 + 6, W, Hh, r);
      /* body */
      g.fillStyle(theme.wall, 1);
      g.fillRoundedRect(x0, y0, W, Hh, r);
      /* top-lit band */
      g.fillStyle(0xffffff, 0.07);
      g.fillRoundedRect(x0, y0, W, Math.max(r * 2, Math.floor(Hh * 0.42)), r);
      /* bevel: light top/left, dark bottom/right */
