    spawnChiliBonus() {
      this.clearChiliBonus();
      var p = this.pickChiliSpot();
      this.chiliFloor = this.add.rectangle(p[0], p[1], 72, 52, 0x8a2010, 0.24).setDepth(2);
      this.chiliFloor.setStrokeStyle(1, 0xffa060, 0.5);
      var spr = this.physics.add.sprite(p[0], p[1], "chili");
      spr.body.setAllowGravity(false);
      spr.body.setImmovable(true);
      try {
        if (spr.body.checkCollision) spr.body.checkCollision.none = true;
        spr.body.moves = false;
        if (spr.body.setEnable) spr.body.setEnable(false);
      } catch (e) {}
      spr.setDepth(11);
      spr.setScale(1.32);
      var lab = this.add.text(p[0], p[1] - 26, "CHILI", {
        fontFamily: "Trebuchet MS", fontSize: 11, color: "#ffc090", fontStyle: "bold",
        stroke: "#4a1008", strokeThickness: 4
      }).setOrigin(0.5).setDepth(12);
      var ring = this.add.circle(p[0], p[1], 22, 0xff6020, 0.22).setDepth(10);
      ring.setStrokeStyle(2, 0xffe0a0, 0.85);
      this.chiliBonus = spr;
      this.chiliLabel = lab;
      this.chiliRing = ring;
      this.chiliLiveMs = 999999;
      this.chiliFlash = Math.max(this.chiliFlash || 0, 2000);
      offerTrapIntro(this, {
        key: LS_TRAP_CHILI,
        title: "Chili Fire",
        body: "CHILI FIRE. Walk on for ~3s hot-sauce breath — burns Hati ahead of you. Touch still catches (not a shield)."
      });
      this.paintHud();
    }

    playerChiliFacing() {
      if (typeof this._playerMoveAng === "number" && isFinite(this._playerMoveAng)) {
        return this._playerMoveAng;
      }
      var dir = this.playerFaceDir || "down";
      if (dir === "left") return Math.PI;
      if (dir === "right") return 0;
      if (dir === "up") return -Math.PI / 2;
      return Math.PI / 2; /* down */
    }

    applyChiliFire() {
      var FIRE_MS = 3400;
      this.chiliFireMs = FIRE_MS;
      this.chiliPulseAcc = 0;
      this.chiliFlash = Math.max(this.chiliFlash || 0, FIRE_MS);
      if (this.clearAmbientHudFlashes) this.clearAmbientHudFlashes();
      this.clearChiliAura();
      if (this.player) {
        this.chiliAura = this.add.circle(this.player.x, this.player.y, 34, 0xff6020, 0.20).setDepth(14);
        this.chiliAura.setStrokeStyle(3, 0xffe08a, 0.9);
        try { this.player.setTint(0xff7040); this._chiliTintOn = true; } catch (e) {}
      }
      safeCamFlash();
      if (window.AfterHoursAudio && AfterHoursAudio.chiliChime) AfterHoursAudio.chiliChime();
      this.setCarryFlagText("CHILI FIRE — spit burns Hati ahead! Catch still real", "prio-chariot");
      this.paintHud();
      /* immediate first pulse so pickup feels punchy */
      this.chiliPulseBurn();
    }

    chiliPulseBurn() {
      if (!this.player || (this.chiliFireMs || 0) <= 0) return;
      var ang = this.playerChiliFacing();
      var px = this.player.x, py = this.player.y;
      var RANGE = 175;
      var HALF = (55 * Math.PI) / 180;
      var i, j, dx, dy, dist, facingDot, dang;
      var hit = 0;
      if (!this.chiliConeGfx) {
        this.chiliConeGfx = this.add.graphics().setDepth(13);
      }
      try {
        var g = this.chiliConeGfx;
        g.clear();
        g.fillStyle(0xff6020, 0.22);
        g.beginPath();
        g.moveTo(px, py);
        g.arc(px, py, RANGE, ang - HALF, ang + HALF, false);
        g.closePath();
        g.fillPath();
        g.lineStyle(2, 0xffe08a, 0.75);
        g.beginPath();
        g.moveTo(px, py);
        g.lineTo(px + Math.cos(ang - HALF) * RANGE, py + Math.sin(ang - HALF) * RANGE);
        g.moveTo(px, py);
        g.lineTo(px + Math.cos(ang + HALF) * RANGE, py + Math.sin(ang + HALF) * RANGE);
        g.strokePath();
      } catch (eG) {}
      if (!this.janitors) return;
      for (i = 0; i < this.janitors.length; i++) {
        j = this.janitors[i];
        if (!j) continue;
        if ((j.eatenMs || 0) > 0 || (j.eyesMs || 0) > 0) continue;
        if (inSafeZone(j.x, j.y)) continue;
        dx = j.x - px; dy = j.y - py;
        dist = hypot(dx, dy);
        if (dist < 8 || dist > RANGE) continue;
        dang = angWrap(Math.atan2(dy, dx) - ang); /* BUGFIX: was an O(|a|) while-loop */
        if (Math.abs(dang) > HALF) continue;
        this.chariotSmashHati(j);
        hit++;
        if (this.player && this.add) {
          try {
            var tag = this.add.text(j.x, j.y - 36, "FIRE!", {
              fontFamily: "Trebuchet MS", fontSize: 20, color: "#ff9040", fontStyle: "bold",
              stroke: "#4a1008", strokeThickness: 5
            }).setOrigin(0.5).setDepth(42);
            if (this.tweens) {
              this.tweens.add({
                targets: tag, y: j.y - 70, alpha: 0, duration: 700, ease: "Cubic.easeOut",
                onComplete: function () { try { tag.destroy(); } catch (eT) {} }
              });
            }
          } catch (eTag) {}
        }
      }
      if (hit > 0) {
        if (window.AfterHoursAudio && AfterHoursAudio.chiliBurn) AfterHoursAudio.chiliBurn();
        safeCamFlash();
      } else if (window.AfterHoursAudio && AfterHoursAudio.chiliBurn) {
        /* soft spit even on miss so timing reads */
        try { AfterHoursAudio.chiliBurn(); } catch (eB) {}
      }
    }

    tickChiliFire(step) {
      if ((this.chiliFlash || 0) > 0) {
        this.chiliFlash = Math.max(0, this.chiliFlash - step);
        if (this.chiliFlash <= 0) this.paintHud();
      }
      if ((this.chiliFireMs || 0) > 0) {
        var prev = this.chiliFireMs;
        this.chiliFireMs = Math.max(0, this.chiliFireMs - step);
        this.chiliPulseAcc = (this.chiliPulseAcc || 0) + step;
        if (this.player && this.chiliAura) {
          var pulse = 28 + 8 * Math.abs(Math.sin((this.time.now || Date.now()) / 110));
          this.chiliAura.setPosition(this.player.x, this.player.y);
          this.chiliAura.setRadius(pulse);
          this.chiliAura.setAlpha(0.16 + 0.12 * Math.abs(Math.sin((this.time.now || Date.now()) / 90)));
        }
        if (this.player && this.player.setTint) {
          try { this.player.setTint(0xff7040); this._chiliTintOn = true; } catch (e) {}
        }
        if (this.chiliPulseAcc >= 380) {
          this.chiliPulseAcc = 0;
          if (this.chiliFireMs > 0) this.chiliPulseBurn();
        }
        if (this.chiliConeGfx) {
          try {
            var fade = Math.max(0, 1 - (this.chiliPulseAcc || 0) / 380);
            this.chiliConeGfx.setAlpha(0.15 + 0.55 * fade);
          } catch (eC) {}
        }
        if (prev > 0 && this.chiliFireMs <= 0) {
          this.clearChiliAura();
          if (this._chiliTintOn && this.player && this.player.clearTint &&
              !(this.hotFootMs > 0) && !(this.lockerPowerMs > 0) && !(this.cornerBoostMs > 0) &&
              !(this.ivyPhaseMs > 0) && !(this.forcefieldMs > 0) && !(this.dogModeMs > 0)) {
            try { this.player.clearTint(); } catch (e2) {}
            this._chiliTintOn = false;
          }
          this.paintHud();
        }
      } else if (this.chiliConeGfx) {
        try { this.chiliConeGfx.clear(); } catch (e3) {}
      }
      if (this.chiliBonus && this.chiliBonus.active) {
        var bob = Math.sin((this.time.now || Date.now()) / 150) * 3;
        if (this.chiliLabel) this.chiliLabel.y = this.chiliBonus.y - 26 + bob;
        if (this.chiliRing) {
          var pulse2 = 20 + 5 * Math.abs(Math.sin((this.time.now || Date.now()) / 135));
          this.chiliRing.setRadius(pulse2);
          this.chiliRing.setPosition(this.chiliBonus.x, this.chiliBonus.y);
        }
        if (this.player && hypot(this.chiliBonus.x - this.player.x, this.chiliBonus.y - this.player.y) < 90) {
          this.clearChiliBonus();
          this.chiliScatterCd = 17000 + Math.floor(Math.random() * 7000);
          this.applyChiliFire();
          return;
        }
        return;
      }
      this.chiliScatterCd = Math.max(0, (this.chiliScatterCd || 0) - step);
      if (this.chiliScatterCd <= 0 && this.stunMs <= 0 && !this.ended && trapUnlocked(this.night, "chili") && (this.chiliFireMs || 0) <= 0) {
        this.spawnChiliBonus();
        this.chiliScatterCd = 999999;
      }
    }


