      if (!this.zapPad || !(this.zapPad.active || this.zapPad.active === undefined)) return;
      var bob = Math.sin((this.time.now || Date.now()) / 140) * 3;
      if (this.zapLabel) this.zapLabel.y = (this.zapPad.y || 0) - 30 + bob;
      if (this.zapRing) {
        var pr = 22 + 6 * Math.abs(Math.sin((this.time.now || Date.now()) / 110));
        this.zapRing.setRadius(pr);
        this.zapRing.setPosition(this.zapPad.x, this.zapPad.y);
      }
      var zx = this.zapPad.x, zy = this.zapPad.y;
      if (this.player && hypot(zx - this.player.x, zy - this.player.y) < 78) {
        var wasStumble = (this.zapStumbleMs || 0) <= 0;
        this.zapStumbleMs = Math.max(this.zapStumbleMs || 0, 1000);
        if (this.player.setTint) {
          try { this.player.setTint(0x80e8ff); this._zapTintOn = true; } catch (eT) {}
        }
        if (wasStumble) {
          this.scoreToastMsg = "ZAP! Stumble — catch still real!";
          this.scoreToastMs = Math.max(this.scoreToastMs || 0, 900);
          this.zapFlash = Math.max(this.zapFlash || 0, 900);
          if (window.AfterHoursAudio && AfterHoursAudio.zapBuzz) AfterHoursAudio.zapBuzz();
        }
      }
      var ji, jj, dx, dy, len, shove;
      if (this.janitors) {
        for (ji = 0; ji < this.janitors.length; ji++) {
          jj = this.janitors[ji];
          if (!jj || !jj.active) continue;
          if ((jj.eatenMs || 0) > 0 || (jj.eyesMs || 0) > 0) continue;
          if (hypot(jj.x - zx, jj.y - zy) >= 78) continue;
          if ((jj.zapHitCd || 0) > 0) continue;
          jj.gateStunMs = Math.max(jj.gateStunMs || 0, 2200);
          jj.allowReverse = true;
          /* Do NOT clear jj.chasing — sticky chase kept */
          dx = jj.x - zx; dy = jj.y - zy;
          len = hypot(dx, dy) || 1;
          shove = 36;
          try {
            jj.x += (dx / len) * shove;
            jj.y += (dy / len) * shove;
            if (jj.body && jj.body.reset) jj.body.reset(jj.x, jj.y);
            if (jj.setVelocity) jj.setVelocity((dx / len) * 120, (dy / len) * 120);
          } catch (eJ) {}
          jj.zapHitCd = 2800;
          if (this.awardBonusPoints) this.awardBonusPoints(100, "ZAP! +100");
          this.zapFlash = Math.max(this.zapFlash || 0, 1600);
          safeCamFlash();
      if (window.AfterHoursAudio && AfterHoursAudio.zapBuzz) AfterHoursAudio.zapBuzz();
          try {
            var tag = this.add.text(jj.x, jj.y - 40, "ZAP!", {
              fontFamily: "Trebuchet MS", fontSize: 18, color: "#c8f8ff", fontStyle: "bold",
              stroke: "#103848", strokeThickness: 5
            }).setOrigin(0.5).setDepth(42);
            if (this.tweens) {
              this.tweens.add({
                targets: tag, y: jj.y - 76, alpha: 0, duration: 850, ease: "Cubic.easeOut",
                onComplete: function () { try { tag.destroy(); } catch (eB) {} }
              });
            } else {
              this.time.delayedCall(850, function () { try { tag.destroy(); } catch (eB2) {} });
            }
          } catch (eT2) {}
          this.paintHud();
        }
      }
