    pickMushSpot() {
      var hallYC = (MAZE && MAZE.hallYC) || START_Y;
      var cands = this.buildSpreadCands();
      if (!cands.length) cands = [[WORLD_W * 0.35, hallYC], [WORLD_W * 0.65, hallYC], [WORLD_W * 0.5, hallYC - 120], [WORLD_W * 0.5, hallYC + 120]];
      var i, p, ok, s, used = [];
      for (i = 0; i < cands.length; i++) {
        p = cands[i];
        if (hitsSolid(p[0], p[1], 36)) continue;
        if (this.spotBlocked(p[0], p[1], 76)) continue;
        if (inSafeZone(p[0], p[1])) continue;
        if (hypot(p[0] - START_X, p[1] - START_Y) < 320) continue;
        if (hypot(p[0] - EXIT_X, p[1] - EXIT_Y) < SLIP_EXIT_R) continue;
        if (inExitCluster(p[0], p[1]) || inStartCluster(p[0], p[1])) continue;
        if (this.fruitBonus && this.fruitBonus.active &&
            hypot(p[0] - this.fruitBonus.x, p[1] - this.fruitBonus.y) < 90) continue;
        if (this.iceBonus && this.iceBonus.active &&
            hypot(p[0] - this.iceBonus.x, p[1] - this.iceBonus.y) < 90) continue;
        if (this.hotFootBonus && this.hotFootBonus.active &&
            hypot(p[0] - this.hotFootBonus.x, p[1] - this.hotFootBonus.y) < 90) continue;
        if (this.moneyBagBonus && this.moneyBagBonus.active &&
            hypot(p[0] - this.moneyBagBonus.x, p[1] - this.moneyBagBonus.y) < 90) continue;
        if (this.horseshoeBonus && this.horseshoeBonus.active &&
            hypot(p[0] - this.horseshoeBonus.x, p[1] - this.horseshoeBonus.y) < 90) continue;
        if (this.chiliBonus && this.chiliBonus.active &&
            hypot(p[0] - this.chiliBonus.x, p[1] - this.chiliBonus.y) < 90) continue;
        if (this.veggieBonus && this.veggieBonus.active &&
            hypot(p[0] - this.veggieBonus.x, p[1] - this.veggieBonus.y) < 90) continue;
        if (this.ivyBonus && this.ivyBonus.active &&
            hypot(p[0] - this.ivyBonus.x, p[1] - this.ivyBonus.y) < 90) continue;
        if (this.heartBonus && this.heartBonus.active &&
            hypot(p[0] - this.heartBonus.x, p[1] - this.heartBonus.y) < 90) continue;
        if (this.boneBonus && this.boneBonus.active &&
            hypot(p[0] - this.boneBonus.x, p[1] - this.boneBonus.y) < 90) continue;
        if (this.extraBonus && this.extraBonus.active &&
            hypot(p[0] - this.extraBonus.x, p[1] - this.extraBonus.y) < 90) continue;
        if (this.treasureBonus && this.treasureBonus.active &&
            hypot(p[0] - this.treasureBonus.x, p[1] - this.treasureBonus.y) < 90) continue;
        if (this.lockPadBonus && this.lockPadBonus.active &&
            hypot(p[0] - this.lockPadBonus.x, p[1] - this.lockPadBonus.y) < 90) continue;
        if (this.pineappleBonus && this.pineappleBonus.active &&
            hypot(p[0] - this.pineappleBonus.x, p[1] - this.pineappleBonus.y) < 90) continue;
        if (this.springBonus && this.springBonus.active &&
            hypot(p[0] - this.springBonus.x, p[1] - this.springBonus.y) < 90) continue;
        if (this.colorDoorBonus && this.colorDoorBonus.active &&
            hypot(p[0] - this.colorDoorBonus.x, p[1] - this.colorDoorBonus.y) < 90) continue;
        if (this.superBonus && this.superBonus.active &&
            hypot(p[0] - this.superBonus.x, p[1] - this.superBonus.y) < 90) continue;
        if (this.zapPad && this.zapPad.active &&
            hypot(p[0] - this.zapPad.x, p[1] - this.zapPad.y) < 90) continue;
        if (this.mushPad && this.mushPad.active &&
            hypot(p[0] - this.mushPad.x, p[1] - this.mushPad.y) < 90) continue;
        if (this.wheelSpr && this.wheelSpr.active &&
            hypot(p[0] - this.wheelSpr.x, p[1] - this.wheelSpr.y) < 90) continue;
        if (this.firePad && this.firePad.active &&
            hypot(p[0] - this.firePad.x, p[1] - this.firePad.y) < 90) continue;
        ok = true;
        if (this.slips) {
          for (s = 0; s < this.slips.length; s++) {
            if (!this.slips[s] || !this.slips[s].visible) continue;
            if (hypot(p[0] - this.slips[s].x, p[1] - this.slips[s].y) < 80) { ok = false; break; }
          }
        }
        if (!ok) continue;
        used.push(p);
      }
      if (!used.length) return [WORLD_W * 0.44, hallYC];
      return used[Math.floor(Math.random() * used.length)];
    }

