      var vx = this.wheelVx || 200;
      var nx = (this.wheelSpr.x || 0) + vx * dtSec;
      var ny = hallYC;
      var leftBound = WORLD_W * 0.16;
      var rightBound = WORLD_W * 0.84;
      var bounce = false;
      if (nx < leftBound) { nx = leftBound; bounce = true; }
      if (nx > rightBound) { nx = rightBound; bounce = true; }
      if (hitsSolid(nx, ny, 34) || hitsSolid(nx + (vx > 0 ? 28 : -28), ny, 30)) {
        bounce = true;
        nx = this.wheelSpr.x;
      }
