        lane = laneById(j.laneId) || (LANES && LANES[i % LANES.length]);
        sx = lane && lane.spawn ? lane.spawn[0] : START_X + 400;
        sy = lane && lane.spawn ? lane.spawn[1] : ((MAZE && MAZE.hallYC) || START_Y);
        if (nearExitJan(sx, sy) || inExitCluster(sx, sy) || inSafeZone(sx, sy) || hypot(sx - EXIT_X, sy - EXIT_Y) < EXIT_JAN) {
          alt = pickPatrolPoint({ x: sx, y: sy, laneId: j.laneId, role: j.role || "wander" }, true);
          if (alt && !(nearExitJan(alt.x, alt.y) || inExitCluster(alt.x, alt.y))) {
            sx = alt.x; sy = alt.y;
          } else {
            jx = (MAZE && MAZE.exitJuncX) || EXIT_X;
            hy = (MAZE && MAZE.hallYC) || START_Y;
            sx = Math.max(280, jx - 420);
            sy = hy;
          }
        }
        if (j.body && j.body.reset) j.body.reset(sx, sy);
        else { j.x = sx; j.y = sy; }
        j.setVelocity(0, 0);
        j.chasing = false;
        j.chaseMs = 0;
        j.chaseFor = 0;
        j.investigate = false;
        j.searching = false;
        j.detFill = 0;
        j.radioSent = false;
        j.radioMs = 0;
        j.patrolTx = null;
        j.patrolTy = null;
        j.gdir = null;
        j.scatter = scatterForGhost(j); /* engage-2214 SCATTER ROLE */
        if (j.scatter) { j.patrolTx = j.scatter.x; j.patrolTy = j.scatter.y; }
