      if (!this.janitors) return;
      var i, jj, best = null, bestMs = 1e15;
      for (i = 0; i < this.janitors.length; i++) {
        jj = this.janitors[i];
        if (!jj || (jj.eatenMs || 0) <= 400) continue;
        if (jj.eatenMs < bestMs) { bestMs = jj.eatenMs; best = jj; }
      }
      if (!best) return;
      best.eatenMs = Math.max(350, best.eatenMs - 1400);
      this.penHoldFlash = Math.max(this.penHoldFlash || 0, 900);
      if (window.AfterHoursAudio && AfterHoursAudio.penNudge) AfterHoursAudio.penNudge();
